function ProgressBar({ step, total }) {
  const progress = (step + 1) / total;

  return (
    <div style={{ marginBottom: 34 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 18, marginBottom: 10 }}>
        {[0, 1, 2].map((segment) => {
          const segmentStart = segment / 3;
          const segmentEnd = (segment + 1) / 3;
          let fill = 0;

          if (progress >= segmentEnd) fill = 100;
          else if (progress > segmentStart) fill = ((progress - segmentStart) / (segmentEnd - segmentStart)) * 100;

          return (
            <div key={segment} style={{ flex: segment === 1 ? 1.35 : 0.38, height: 4, background: "#D9DDE7", borderRadius: 999, overflow: "hidden" }}>
              <div style={{ width: `${fill}%`, height: "100%", background: "#3344C9", borderRadius: 999, transition: "width .25s ease" }} />
            </div>
          );
        })}
      </div>
      <div style={{ textAlign: "center", fontSize: 10, color: "#8C8FA1" }}>
        Step {step + 1} of {total}
      </div>
    </div>
  );
}

