function renderOptionIcon(icon) {
  if (!icon) return null;

  if (typeof icon === "string") {
    const isAssetPath =
      icon.startsWith("/") ||
      icon.startsWith("./") ||
      icon.startsWith("../") ||
      icon.startsWith("data:") ||
      icon.includes(".svg") ||
      icon.includes(".png") ||
      icon.includes(".jpg") ||
      icon.includes(".jpeg") ||
      icon.includes(".webp");

    if (isAssetPath) {
      return <img src={icon} alt="" style={{ width: 20, height: 20, objectFit: "contain", display: "block" }} />;
    }

    return <span style={{ fontSize: 21 }}>{icon}</span>;
  }

  return icon;
}

const LARGE_RADIUS_STEP_IDS = new Set([
  "identity_gender",
  "identity_ethnicity",
  "skin_concerns",
  "routine_products",
  "routine_preference",
  "body",
  "budget",
  "fitness",
]);

function getOptionRadius(stepId) {
  return LARGE_RADIUS_STEP_IDS.has(stepId) ? 30 : 18;
}

function OptionButton({ label, icon, selected, onClick, detail, circle = false, borderRadius = 18 }) {
  return (
    <button
      onClick={onClick}
      style={{
        width: "100%",
        borderRadius,
        border: `1px solid ${selected ? "#7386FF" : "#E7E7EC"}`,
        background: selected ? "#F6F7FF" : "#FFFFFF",
        minHeight: detail ? 74 : 54,
        padding: detail ? "14px 16px" : "0 16px",
        textAlign: "left",
        display: "flex",
        alignItems: detail ? "flex-start" : "center",
        gap: 14,
        cursor: "pointer",
        boxShadow: "0 8px 20px rgba(15, 23, 42, 0.05)",
      }}
      >
      {icon ? (
        <div style={{ width: detail ? 38 : 20, display: "flex", justifyContent: "center", flexShrink: 0, paddingTop: detail ? 3 : 0 }}>
          {renderOptionIcon(icon)}
        </div>
      ) : null}
      <div style={{ flex: 1 }}>
        <div style={{ fontSize: 15, fontWeight: 500, color: "#17181F" }}>{label}</div>
        {detail ? <div style={{ marginTop: 5, fontSize: 12, lineHeight: 1.45, color: "#6F7487" }}>{detail}</div> : null}
      </div>
      {circle ? (
        <div style={{
          width: 16,
          height: 16,
          borderRadius: "50%",
          border: `1.5px solid ${selected ? "#3344C9" : "#D3D7E1"}`,
          background: selected ? "#3344C9" : "#FFFFFF",
          boxShadow: selected ? "inset 0 0 0 4px #FFFFFF" : "none",
          flexShrink: 0,
          marginTop: detail ? 3 : 0,
        }} />
      ) : null}
    </button>
  );
}

