function StepRenderer({ step, value, setValue, onAfterSelect }) {
  if (step.type === "single") return <SingleStep step={step} value={value} setValue={setValue} onAfterSelect={onAfterSelect} />;
  if (step.type === "singleChoice") return <SingleChoiceStep step={step} value={value} setValue={setValue} />;
  if (step.type === "singleDetailed") return <SingleDetailedStep step={step} value={value} setValue={setValue} onAfterSelect={onAfterSelect} />;
  if (step.type === "multi") return <MultiStep step={step} value={value} setValue={setValue} />;
  if (step.type === "location") return <LocationStep step={step} value={value} setValue={setValue} />;
  if (step.type === "faceAreas") return <FaceAreaStep step={step} value={value} setValue={setValue} />;
  if (step.type === "body") return <BodyStep step={step} value={value} setValue={setValue} />;
  if (step.type === "sleep") return <SleepStep value={value} setValue={setValue} />;
  if (step.type === "personalize") return <PersonalizationStep value={value} setValue={setValue} />;
  if (step.type === "dob") return <DateOfBirthStep value={value} setValue={setValue} />;
  return null;
}

export default function Onboarding({ onComplete, onBack }) {
  const [stepIndex, setStepIndex] = useState(0);
  const [answers, setAnswers] = useState({});
  const [dir, setDir] = useState(1);

  const step = STEPS[stepIndex];
  const value = answers[step.id];
  const valid = isValid(step, value);
  const hideContinue = !!step.autoAdvance;

  const setValue = (nextValue) => {
    setAnswers((current) => ({ ...current, [step.id]: nextValue }));
  };

  const handleBack = () => {
    if (stepIndex === 0) {
      if (onBack) onBack();
      return;
    }
    setDir(-1);
    setStepIndex((current) => current - 1);
  };

  const handleContinue = () => {
    if (!valid) return;
    if (stepIndex === STEPS.length - 1) {
      onComplete(normalizeAnswers(answers));
      return;
    }
    setDir(1);
    setStepIndex((current) => current + 1);
  };

  const handleSkip = () => {
    if (stepIndex === STEPS.length - 1) {
      onComplete(normalizeAnswers(answers));
      return;
    }
    setDir(1);
    setStepIndex((current) => current + 1);
  };

  const handleAutoAdvance = (nextValue) => {
    if (!step.autoAdvance || !isValid(step, nextValue)) return;
    window.setTimeout(() => {
      setDir(1);
      setStepIndex((current) => {
        if (current !== stepIndex) return current;
        return Math.min(current + 1, STEPS.length - 1);
      });
    }, 120);
  };

  return (
    <div style={shellStyle}>
      <style>{GLOBAL_CSS}</style>
      <div style={{ maxWidth: 420, minHeight: "100vh", margin: "0 auto", background: "#FFFFFF", padding: "26px 20px 132px", position: "relative" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 12 }}>
          <BackButton onClick={handleBack} />
          <div style={{ flex: 1 }}>
            <ProgressBar step={stepIndex} total={STEPS.length} />
          </div>
        </div>

        <div
          key={step.id}
          style={{
            animation: `${dir > 0 ? "slideInR" : "slideInL"} .28s ease`,
          }}
        >
          {step.eyebrow ? (
            <div style={{ margin: "0 0 10px", fontSize: 11, letterSpacing: 2.2, color: "#9AA0B4" }}>
              {step.eyebrow}
            </div>
          ) : null}
          <h1 style={{ margin: "0 0 10px", fontSize: 24, lineHeight: 1.15, fontWeight: 400 }}>
            {step.title}
          </h1>
          {step.sub ? (
            <p style={{ margin: "0 0 26px", fontSize: 13, lineHeight: 1.45, color: "#000000", fontWeight: 400, maxWidth: 340 }}>
              {step.sub}
            </p>
          ) : (
            <div style={{ height: 18 }} />
          )}

          <StepRenderer step={step} value={value} setValue={setValue} onAfterSelect={handleAutoAdvance} />
        </div>

        {!hideContinue && (
          <div style={{
            position: "fixed",
            left: "50%",
            bottom: 0,
            transform: "translateX(-50%)",
            width: "min(420px, 100%)",
            padding: "16px 20px 24px",
            background: "linear-gradient(180deg, rgba(255,255,255,0) 0%, rgba(255,255,255,.96) 28%, #FFFFFF 100%)",
          }}>
            <button
              onClick={handleContinue}
              disabled={!valid}
              style={{
                width: "100%",
                minHeight: 52,
                border: "none",
                borderRadius: 30,
                background: valid ? "#202A95" : "#C9CDE8",
                color: "#FFFFFF",
                fontSize: 16,
                fontWeight: 700,
                cursor: valid ? "pointer" : "not-allowed",
                boxShadow: valid ? "0 16px 28px rgba(32, 42, 149, 0.22)" : "none",
              }}
            >
              {stepIndex === STEPS.length - 1 ? "Continue to photo capture" : "Continue"}
            </button>
            {step.type === "personalize" ? (
              <button
                onClick={handleSkip}
                style={{
                  width: "100%",
                  marginTop: 12,
                  border: "none",
                  background: "transparent",
                  color: "#8C8FA1",
                  fontSize: 14,
                  textDecoration: "underline",
                  cursor: "pointer",
                }}
              >
                Skip for now
              </button>
            ) : null}
          </div>
        )}
      </div>
    </div>
  );
}
